"""Single local image loader with EXIF orientation normalization."""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
from pathlib import Path
from time import perf_counter
from typing import Any


class ImageLoadError(ValueError):
    pass


SUPPORTED_SUFFIXES = {".jpg", ".jpeg", ".png", ".webp", ".bmp"}
SUPPORTED_FORMATS = {"JPEG", "PNG", "WEBP", "BMP"}


@dataclass(frozen=True)
class LoadedImage:
    path: Path
    image: Any
    width: int
    height: int
    format: str
    original_mode: str
    exif_orientation: int | None
    exif_transposed: bool
    file_size_bytes: int
    sha256: str
    load_ms: float

    def to_dict(self) -> dict:
        return {
            "path": str(self.path),
            "width": self.width,
            "height": self.height,
            "format": self.format,
            "original_mode": self.original_mode,
            "exif_orientation": self.exif_orientation,
            "exif_transposed": self.exif_transposed,
            "file_size_bytes": self.file_size_bytes,
            "sha256": self.sha256,
        }


def load_image(path: Path) -> LoadedImage:
    started = perf_counter()
    path = path.expanduser().resolve()
    if not path.is_file():
        raise ImageLoadError(f"Image file was not found: {path}")
    if path.suffix.lower() not in SUPPORTED_SUFFIXES:
        raise ImageLoadError(
            f"Unsupported image extension {path.suffix!r}; supported: JPG, JPEG, PNG, WEBP, BMP"
        )
    try:
        from PIL import Image, ImageOps, UnidentifiedImageError
    except ImportError as exc:
        raise ImageLoadError(
            'Image support requires Pillow. Install with: pip install -e ".[vision]"'
        ) from exc
    raw = path.read_bytes()
    try:
        with Image.open(path) as opened:
            image_format = opened.format or "unknown"
            if image_format.upper() not in SUPPORTED_FORMATS:
                raise ImageLoadError(f"Unsupported decoded image format: {image_format}")
            original_mode = opened.mode
            orientation = opened.getexif().get(274)
            normalized = ImageOps.exif_transpose(opened)
            image = normalized.convert("RGB")
            image.load()
    except ImageLoadError:
        raise
    except (UnidentifiedImageError, OSError, ValueError) as exc:
        raise ImageLoadError(f"Image is corrupted or cannot be decoded: {path}") from exc
    return LoadedImage(
        path=path,
        image=image,
        width=image.width,
        height=image.height,
        format=image_format.upper(),
        original_mode=original_mode,
        exif_orientation=orientation,
        exif_transposed=orientation not in (None, 1),
        file_size_bytes=len(raw),
        sha256=hashlib.sha256(raw).hexdigest(),
        load_ms=(perf_counter() - started) * 1000,
    )
